// Cloudflare entry point: the OpenNext app, plus a cron that keeps FalkorDB Cloud awake.
// Free FalkorDB Cloud instances stop after a period with no activity; a small write every
// 10 minutes counts as activity.
// @ts-expect-error -- generated by `opennextjs-cloudflare build`
import { default as app } from "./.open-next/worker.js";
import { FalkorDB } from "falkordb";

export default {
  fetch: app.fetch,
  async scheduled(_event: unknown, env: { FALKORDB_URL?: string }) {
    if (!env.FALKORDB_URL) return;
    const db = await FalkorDB.connect({ url: env.FALKORDB_URL });
    try {
      await db.selectGraph("weft_keepalive").query("MERGE (p:Ping {id:1}) SET p.at = $at", { params: { at: new Date().toISOString() } });
    } finally {
      await db.close();
    }
  },
};

// @ts-expect-error -- generated by `opennextjs-cloudflare build`
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";
